import {mkdtempSync,realpathSync,mkdirSync,writeFileSync,rmSync,readFileSync} from 'node:fs';
import {join} from 'node:path';import {tmpdir} from 'node:os';import {execFileSync} from 'node:child_process';
import {createNativeProjectService,inspectSourceInventory} from '../../dist/host/project/native-project.js';
import {nativeSha256 as hash,nativeBytesDigest,NATIVE_CONTRACT_DIGEST,validateNativePackage} from '../../vendor/compatibility/v1/native.mjs';
import {syntheticReadinessMaterial} from './adapters-v090.mjs';
import {syntheticDecisionEvidence} from './native/decision-evidence.mjs';
export const put=(p,v)=>writeFileSync(p,typeof v==='string'?v:JSON.stringify(v),{mode:0o600});
export function rehash(pkg){pkg.manifest.files=Object.entries(pkg.files).sort(([a],[b])=>a.localeCompare(b,'en')).map(([path,text])=>({path,mediaType:path.endsWith('.ttl')?'text/turtle':'application/json',sha256:nativeBytesDigest(text).slice(7)}));return pkg;}
// Minimal contract-shaped source fixtures with explicitly synthetic validators.
// Actual public owner semantic/native validation is a separate integration probe.
export function projectFixture({direction='forward',visibility='private',level='L3'}={}){
 const root=mkdtempSync(join(realpathSync(tmpdir()),'runtime-project-compat-')),projectRoot=join(root,'project'),stateRoot=join(root,'state'),source=join(root,'source'),workspaceId='synthetic-project-host',scope={visibility,projectId:'synthetic'};
 for(const p of [projectRoot,stateRoot,source])mkdirSync(p,{mode:0o700});
 put(join(projectRoot,'workspace-project.json'),{schema:'evopilot-workspace-project/v1',id:workspaceId,templateVersion:'0.2.0',specifications:{ontology:'v1',harness:'v1'}});put(join(stateRoot,'workspace.json'),{schema:'evopilot-workspace/v1',id:workspaceId,canonicalRoot:stateRoot,ownerUid:process.getuid()});
 const content='An explicitly synthetic declared project contract.\n';for(const o of ['ontology','harness'])put(join(source,o+'.txt'),content);put(join(source,'package.json'),{private:true,name:'synthetic-input'});
 const git=(...args)=>execFileSync('/usr/bin/git',['-c','core.hooksPath=/dev/null','-C',source,...args],{env:{PATH:'/usr/bin:/bin',GIT_CONFIG_NOSYSTEM:'1',GIT_CONFIG_GLOBAL:'/dev/null',GIT_AUTHOR_NAME:'Synthetic Test',GIT_AUTHOR_EMAIL:'test@example.invalid',GIT_COMMITTER_NAME:'Synthetic Test',GIT_COMMITTER_EMAIL:'test@example.invalid'},stdio:['ignore','pipe','pipe']}).toString().trim();
 let revision='requirements-one';if(direction==='reverse'){git('init','-q');git('add','.');git('commit','-qm','Synthetic source fixture');revision=git('rev-parse','HEAD');}
 const packages=Object.fromEntries(['ontology','harness'].map(owner=>{
  const bindings={schema:'evopilot-source-bindings/v1',direction,sources:[{id:'source',locator:owner+'.txt',revision,digest:nativeBytesDigest(content),status:'observed',visibility,contentPath:'sources/source.txt'}],requirements:[{id:owner+':scope',required:true,disposition:'covered'}],mappings:[{requirementId:owner+':scope',targetId:owner+'-entity',sourceId:'source',status:'inferred',rationale:'Synthetic mapping requires a separate domain decision',revision,fileDigest:nativeBytesDigest(content),selector:{kind:'lines',start:1,end:content.split('\n').length},fragmentDigest:nativeBytesDigest(content)}]};
  const files={'sources/source.txt':content,'source-bindings.json':JSON.stringify(bindings),...(owner==='ontology'?{'model.ttl':'# Synthetic model\n','tests/cases.json':JSON.stringify({cases:[{id:'positive',requirementIds:['ontology:scope']},{id:'negative',requirementIds:['ontology:scope']}]})}:{'coverage.json':JSON.stringify({requirements:[{id:'harness:scope',caseIds:['positive','negative']}]})})};
  return[owner,rehash({manifest:{schema:'evopilot-native-package/v1',specVersion:'v1',owner,id:'synthetic-'+owner,version:'1.0.0',visibility,standardPins:{standardDigest:hash(owner+'-standard'),standardLockDigest:hash(owner+'-lock')},contractDigest:NATIVE_CONTRACT_DIGEST,producer:{product:owner,version:'0.3.0'},entrypoints:owner==='ontology'?{cases:'tests/cases.json',model:'model.ttl'}:{coverage:'coverage.json'},files:[],dependencies:[],sourceBindingRef:'source-bindings.json'},files})];
 }));
 const requirements={schema:'evopilot-project-requirements/v1',projectId:scope.projectId,direction,ownerRequirements:['ontology','harness'].map(owner=>({criterionId:owner+':scope',variantIds:owner==='ontology'?['positive','negative']:['positive','negative','actual-observation'],origin:direction==='forward'?'design-declaration':'source-declaration',description:'Independent synthetic '+owner+' requirement',sourceIds:[owner+'.txt']})),modules:[{id:'.',disposition:'included',requirementIds:['ontology:scope','harness:scope'],reason:'One synthetic module'}],capabilities:[{id:'inspect',requirementIds:['ontology:scope','harness:scope']}],exclusions:[]};
 const definition={...syntheticReadinessMaterial(workspaceId,scope.projectId).definition,scope,mode:direction==='reverse'?'SOURCE_REVERSE':'DOCUMENT_FORWARD',targetLevel:level,sources:[{id:'fixture-design',kind:direction==='reverse'?'SOURCE':'DOCUMENT',reference:source,revision,digest:inspectSourceInventory(source,direction,revision).treeDigest}],requirements:requirements.ownerRequirements.map(r=>({id:r.criterionId,kind:r.criterionId.startsWith('ontology:')?'DOMAIN':'BEHAVIOR',description:r.description,acceptance:'The independent variants are preserved',acceptanceVariants:r.variantIds,sourceIds:['fixture-design'],excludedFacets:[]}))};
 const modelingIntent={definition,humanEvidenceRef:syntheticDecisionEvidence(root,{owner:'runtime',operation:'readiness.intent.record',workspaceId,scope,reviewDigest:hash(definition),decision:'ACCEPT'})};
 const input={id:'round-one',scope,sourceRoot:source,direction,revision,requirements,standardPins:Object.fromEntries(Object.entries(packages).map(([o,p])=>[o,p.manifest.standardPins])),modelingIntent};
 const control={valid:true,active:true,completed:null,afterValidation:null,validationCalls:0};
 const ownerValidation={validateOntologyPackage:(p)=>validateNativePackage(p),inspectHarnessPackage:(p)=>validateNativePackage(p),async validateNativeOntology(){control.validationCalls++;await control.afterValidation?.();return{status:control.valid?'CONFORMS':'NONCONFORMING',reportDigest:hash('synthetic-validation'),toolchainLockDigest:hash('synthetic-toolchain')};}};
 const trusted={ownerValidation,nativeToolchain:()=>({synthetic:true}),assertCurrent:()=>{if(!control.active)throw Object.assign(Error('Synthetic config revoked'),{code:'OWNER_HOST_CHANGED'});},readCompletedProject:async()=>control.completed??{complete:null}};
 const context={projectRoot,stateRoot,workspaceId},service=createNativeProjectService(context,trusted);
 const decision=(operation,reviewDigest,decision='ACCEPT')=>syntheticDecisionEvidence(root,{owner:'project',operation,workspaceId,scope,reviewDigest,decision});
 async function freeze(){const candidate=await service.prepare(input);return service.freeze({scope,id:input.id,packages,reviewDigest:candidate.reviewDigest,humanEvidenceRef:decision('freeze',candidate.reviewDigest)});}
 return{root,projectRoot,stateRoot,source,workspaceId,scope,context,service,input,packages,control,trusted,git,decision,freeze,cleanup:()=>rmSync(root,{recursive:true,force:true})};
}
